def read_webpage(url, idempotency_key=None, **_extra):
    import json, os, datetime, hashlib, secrets, time, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0217000" if __import__("os").path.isdir("./environment_mix/0217000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        ms = int(time.time() * 1000)
        ts = ms.to_bytes(6, "big", signed=False)
        rand = secrets.token_bytes(10)
        n = int.from_bytes(ts + rand, "big")
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(_CROCKFORD[r])
        return f"{prefix}_" + "".join(reversed(out))

    def _parse_bearer(v):
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.lower().startswith("bearer "):
            s = s[7:].strip()
        return s or None

    def _extract_token(extra):
        # Accept common carriers
        for k in ("api_key", "apiKey", "key", "token", "authorization", "Authorization", "x_api_key", "x-api-key"):
            if k in extra:
                tok = _parse_bearer(extra.get(k))
                if tok:
                    return tok
        return None

    def _resolve_context():
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        if not isinstance(api_keys, list): api_keys = []
        if not isinstance(workspaces, list): workspaces = []

        token = _extract_token(_extra)

        # If a token is explicitly provided, authenticate by id OR by key_prefix match.
        # IMPORTANT: do NOT verify against key_hash using plaintext (plaintext isn't stored).
        # We treat providing the correct key id or prefix as sufficient for this offline store.
        if token:
            # by id
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == token and k.get("status") == "active":
                    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
                    if ws and ws.get("status") in ("active", "suspended", "closed"):
                        return k, ws, "id"
            # by prefix (client-visible)
            for k in api_keys:
                if not isinstance(k, dict) or k.get("status") != "active":
                    continue
                kp = k.get("key_prefix")
                if isinstance(kp, str) and kp and token.startswith(kp):
                    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
                    if ws and ws.get("status") in ("active", "suspended", "closed"):
                        return k, ws, "prefix"
            return None, None, "invalid_api_key"

        # Ambient auth: pick any active key whose workspace is active/suspended/closed.
        # Choose a combination that exists.
        for k in api_keys:
            if not isinstance(k, dict) or k.get("status") != "active":
                continue
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
            if ws and ws.get("status") in ("active", "suspended", "closed"):
                return k, ws, "ambient"
        return None, None, "missing_api_key"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _quota_window(now_dt, period):
        # returns (start, end)
        if period == "minute":
            start = now_dt.replace(second=0, microsecond=0)
            end = start + datetime.timedelta(minutes=1)
        elif period == "hour":
            start = now_dt.replace(minute=0, second=0, microsecond=0)
            end = start + datetime.timedelta(hours=1)
        elif period == "day":
            start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0)
            end = start + datetime.timedelta(days=1)
        elif period == "month":
            start = now_dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            y, m = start.year, start.month
            if m == 12:
                end = start.replace(year=y + 1, month=1)
            else:
                end = start.replace(month=m + 1)
        else:
            return None, None
        return start, end

    def _get_or_make_bucket(quota_rows, workspace_id, period, now_dt):
        ps, pe = _quota_window(now_dt, period)
        if ps is None:
            return None
        ps_i = _iso(ps)
        pe_i = _iso(pe)
        for b in quota_rows:
            if not isinstance(b, dict):
                continue
            if b.get("workspace_id") == workspace_id and b.get("period") == period and b.get("period_start") == ps_i:
                return b
        # If none exists, cannot infer limits safely; treat as missing entitlement -> UNAUTHORIZED (no serving combination)
        return None

    def _enforce_quota_or_fail(tool_req_row, quota_rows, ws_id, estimated_cost):
        now_dt = _now()
        # Try to find any bucket for current window across periods; enforce against all that exist.
        # If no buckets at all for this workspace, refuse as UNAUTHORIZED (no serving combination).
        ws_buckets = [b for b in quota_rows if isinstance(b, dict) and b.get("workspace_id") == ws_id]
        if not ws_buckets:
            tool_req_row["status"] = "failed"
            tool_req_row["error"] = {"code": "quota_exceeded", "message": "No quota bucket configured for workspace"}
            tool_req_row["updated_at"] = _iso(now_dt)
            tool_req_row["completed_at"] = _iso(now_dt)
            return False, "UNAUTHORIZED", "No quota bucket configured for workspace"

        # Enforce on the matching current-window bucket(s) by period.
        enforced_any = False
        for period in ("minute", "hour", "day", "month"):
            b = _get_or_make_bucket(quota_rows, ws_id, period, now_dt)
            if not b:
                continue
            enforced_any = True
            mr = b.get("max_requests")
            ur = b.get("used_requests")
            mc = b.get("max_upstream_cost_usd_micros")
            uc = b.get("used_upstream_cost_usd_micros")
            if not isinstance(mr, int) or not isinstance(ur, int) or not isinstance(mc, int) or not isinstance(uc, int):
                tool_req_row["status"] = "failed"
                tool_req_row["error"] = {"code": "quota_exceeded", "message": "Invalid quota bucket configuration"}
                tool_req_row["updated_at"] = _iso(now_dt)
                tool_req_row["completed_at"] = _iso(now_dt)
                return False, "UNAUTHORIZED", "Invalid quota bucket configuration"
            if ur + 1 > mr or uc + int(estimated_cost) > mc:
                tool_req_row["status"] = "failed"
                tool_req_row["error"] = {"code": "quota_exceeded", "message": "Quota exceeded for current window"}
                tool_req_row["updated_at"] = _iso(now_dt)
                tool_req_row["completed_at"] = _iso(now_dt)
                return False, "QUOTA_EXCEEDED", "Quota exceeded for current window"
        if not enforced_any:
            # Buckets exist but none match current window; treat as unauthorized configuration.
            tool_req_row["status"] = "failed"
            tool_req_row["error"] = {"code": "quota_exceeded", "message": "No active quota window found for workspace"}
            tool_req_row["updated_at"] = _iso(now_dt)
            tool_req_row["completed_at"] = _iso(now_dt)
            return False, "UNAUTHORIZED", "No active quota window found for workspace"
        return True, None, None

    def _account_quota_once(quota_rows, ws_id, upstream_cost, tool_request_id):
        # Charge all matching current-window buckets once (best-effort deterministic via charged flag on tool_request output)
        now_dt = _now()
        for period in ("minute", "hour", "day", "month"):
            b = _get_or_make_bucket(quota_rows, ws_id, period, now_dt)
            if not b:
                continue
            b["used_requests"] = int(b.get("used_requests", 0)) + 1
            b["used_upstream_cost_usd_micros"] = int(b.get("used_upstream_cost_usd_micros", 0)) + int(upstream_cost)
            b["updated_at"] = _iso(now_dt)

    # ---- Validate input ----
    if not isinstance(url, str) or not url.strip():
        return _err("VALIDATION_ERROR", "url must be a non-empty string")
    url = url.strip()
    try:
        pu = urllib.parse.urlparse(url)
    except Exception:
        return _err("VALIDATION_ERROR", "url is invalid")
    if pu.scheme not in ("http", "https") or not pu.netloc:
        return _err("VALIDATION_ERROR", "url must be an absolute http(s) URL")

    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided")
    if isinstance(idempotency_key, str):
        idempotency_key = idempotency_key.strip()

    t0 = time.time()
    api_key_row, ws_row, auth_reason = _resolve_context()
    if not api_key_row or not ws_row:
        # Log attempt if possible? No workspace context => cannot create tool_requests row.
        return _err("UNAUTHORIZED", "API key is missing or invalid", reason=auth_reason)

    tool_requests = _load("tool_requests.json")
    if not isinstance(tool_requests, list):
        tool_requests = []

    # Idempotency: if a matching row exists, return it (no double-charge).
    if idempotency_key:
        for tr in tool_requests:
            if not isinstance(tr, dict):
                continue
            if tr.get("workspace_id") == ws_row.get("id") and tr.get("api_key_id") == api_key_row.get("id") and tr.get("tool_name") == "read_webpage" and tr.get("idempotency_key") == idempotency_key:
                # audit last_used and request log update
                now_dt = _now()
                api_keys = _load("api_keys.json")
                if isinstance(api_keys, list):
                    for k in api_keys:
                        if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                            k["last_used_at"] = _iso(now_dt)
                            k["updated_at"] = _iso(now_dt)
                            break
                    _save("api_keys.json", api_keys)
                tr_out = {
                    "tool_request": tr,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "idempotent_replay": True,
                }
                return tr_out

    # Create tool_request row (exactly one per invocation)
    now_dt = _now()
    req_id = _new_ulid("jina_req")
    tr = {
        "id": req_id,
        "workspace_id": ws_row.get("id"),
        "api_key_id": api_key_row.get("id"),
        "tool_name": "read_webpage",
        "status": "queued",
        "input": {"url": url, "idempotency_key": idempotency_key} if idempotency_key else {"url": url},
        "output": None,
        "error": None,
        "idempotency_key": idempotency_key,
        "client_ip": _extra.get("client_ip") if isinstance(_extra.get("client_ip"), str) else None,
        "user_agent": _extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None,
        "upstream_provider": "jina_ai",
        "upstream_endpoint": "/v1/read",
        "upstream_request_id": None,
        "upstream_latency_ms": None,
        "total_latency_ms": None,
        "upstream_cost_usd_micros": 0,
        "created_at": _iso(now_dt),
        "updated_at": _iso(now_dt),
        "started_at": None,
        "completed_at": None,
    }

    # Workspace inactive rule: still log as failed
    if ws_row.get("status") in ("suspended", "closed"):
        tr["status"] = "failed"
        tr["error"] = {"code": "workspace_inactive", "message": f"Workspace status is {ws_row.get('status')}"}
        tr["completed_at"] = _iso(now_dt)
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        # update last_used_at on successful authentication (even if inactive workspace, auth succeeded)
        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list):
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                    k["last_used_at"] = _iso(now_dt)
                    k["updated_at"] = _iso(now_dt)
                    break
            _save("api_keys.json", api_keys)
        tr["total_latency_ms"] = int((time.time() - t0) * 1000)
        tr["updated_at"] = _iso(_now())
        _save("tool_requests.json", tool_requests)
        return {"tool_request": tr}

    # Transition queued->running with quota check
    quota_rows = _load("quota_buckets.json")
    if not isinstance(quota_rows, list):
        quota_rows = []

    # estimated cost (simple deterministic heuristic)
    estimated_cost = 1000  # 0.001 USD micros? actually 1000 micro-USD = $0.001
    ok, fail_code, fail_msg = _enforce_quota_or_fail(tr, quota_rows, ws_row.get("id"), estimated_cost)
    if not ok:
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        # update key last_used_at
        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list):
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                    k["last_used_at"] = _iso(_now())
                    k["updated_at"] = _iso(_now())
                    break
            _save("api_keys.json", api_keys)
        return _err(fail_code, fail_msg, tool_request=tr, reason="quota_exceeded")

    # legal transition
    tr["status"] = "running"
    tr["started_at"] = _iso(_now())
    tr["updated_at"] = tr["started_at"]

    # "Upstream" execution: reuse existing webpage artifacts if any for the URL, else create a minimal one.
    web_artifacts = _load("web_artifacts.json")
    if not isinstance(web_artifacts, list):
        web_artifacts = []

    # Find any existing webpage artifact text/html for this workspace+url to use as content seed
    existing = None
    for a in web_artifacts:
        if isinstance(a, dict) and a.get("workspace_id") == ws_row.get("id") and a.get("artifact_type") == "webpage" and a.get("source_url") == url:
            if a.get("content_text") or a.get("content_html"):
                existing = a
                break

    content_text = existing.get("content_text") if existing else f"Fetched content for {url}"
    content_html = existing.get("content_html") if existing else None
    if not content_text and not content_html:
        content_text = f"Fetched content for {url}"

    # Create webpage artifact linked to this request (FK integrity)
    art_id = _new_ulid("jina_art")
    sha = hashlib.sha256(((content_text or "") + (content_html or "")).encode("utf-8")).hexdigest()
    now2 = _now()
    artifact = {
        "id": art_id,
        "workspace_id": ws_row.get("id"),
        "tool_request_id": req_id,
        "artifact_type": "webpage",
        "source_url": url,
        "title": existing.get("title") if existing else None,
        "content_text": content_text,
        "content_html": content_html,
        "snippet": None,
        "metadata": {"fetched_at": _iso(now2), "source": "jina_ai"},
        "content_sha256": sha,
        "expires_at": None,
        "created_at": _iso(now2),
        "updated_at": _iso(now2),
    }

    # Enforce unique(workspace_id, artifact_type, source_url, content_sha256) when both not null
    for a in web_artifacts:
        if not isinstance(a, dict):
            continue
        if a.get("workspace_id") == artifact["workspace_id"] and a.get("artifact_type") == "webpage" and a.get("source_url") == url and a.get("content_sha256") == sha:
            # Deduplicate: reuse existing artifact and don't insert
            artifact = a
            break
    else:
        web_artifacts.append(artifact)
        _save("web_artifacts.json", web_artifacts)

    # Complete succeeded; output must be non-null only for succeeded
    done = _now()
    tr["status"] = "succeeded"
    tr["output"] = {
        "url": url,
        "title": artifact.get("title"),
        "content_text": artifact.get("content_text"),
        "content_html": artifact.get("content_html"),
        "artifact_id": artifact.get("id"),
        "metadata": artifact.get("metadata"),
    }
    tr["error"] = None
    tr["upstream_request_id"] = _new_ulid("jina_up")
    tr["upstream_latency_ms"] = max(1, int((time.time() - t0) * 1000) - 1)
    tr["upstream_cost_usd_micros"] = int(estimated_cost)
    tr["completed_at"] = _iso(done)
    tr["total_latency_ms"] = int((time.time() - t0) * 1000)
    tr["updated_at"] = _iso(done)

    tool_requests.append(tr)
    _save("tool_requests.json", tool_requests)

    # Update api key last_used_at
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                k["last_used_at"] = _iso(done)
                k["updated_at"] = _iso(done)
                break
        _save("api_keys.json", api_keys)

    # Account quota exactly once (since not idempotent replay)
    _account_quota_once(quota_rows, ws_row.get("id"), tr["upstream_cost_usd_micros"], tr["id"])
    _save("quota_buckets.json", quota_rows)

    return {"tool_request": tr}

def search_web(query, limit=None, idempotency_key=None, **_extra):
    import json, os, datetime, secrets, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0217000" if __import__("os").path.isdir("./environment_mix/0217000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        ms = int(time.time() * 1000)
        ts = ms.to_bytes(6, "big", signed=False)
        rand = secrets.token_bytes(10)
        n = int.from_bytes(ts + rand, "big")
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(_CROCKFORD[r])
        return f"{prefix}_" + "".join(reversed(out))

    def _parse_bearer(v):
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.lower().startswith("bearer "):
            s = s[7:].strip()
        return s or None

    def _extract_token(extra):
        for k in ("api_key", "apiKey", "key", "token", "authorization", "Authorization", "x_api_key", "x-api-key"):
            if k in extra:
                tok = _parse_bearer(extra.get(k))
                if tok:
                    return tok
        return None

    def _resolve_context():
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        if not isinstance(api_keys, list): api_keys = []
        if not isinstance(workspaces, list): workspaces = []

        token = _extract_token(_extra)
        if token:
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == token and k.get("status") == "active":
                    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
                    if ws and ws.get("status") in ("active", "suspended", "closed"):
                        return k, ws, "id"
            for k in api_keys:
                if not isinstance(k, dict) or k.get("status") != "active":
                    continue
                kp = k.get("key_prefix")
                if isinstance(kp, str) and kp and token.startswith(kp):
                    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
                    if ws and ws.get("status") in ("active", "suspended", "closed"):
                        return k, ws, "prefix"
            return None, None, "invalid_api_key"

        for k in api_keys:
            if not isinstance(k, dict) or k.get("status") != "active":
                continue
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
            if ws and ws.get("status") in ("active", "suspended", "closed"):
                return k, ws, "ambient"
        return None, None, "missing_api_key"

    def _quota_window(now_dt, period):
        if period == "minute":
            start = now_dt.replace(second=0, microsecond=0); end = start + datetime.timedelta(minutes=1)
        elif period == "hour":
            start = now_dt.replace(minute=0, second=0, microsecond=0); end = start + datetime.timedelta(hours=1)
        elif period == "day":
            start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0); end = start + datetime.timedelta(days=1)
        elif period == "month":
            start = now_dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            y, m = start.year, start.month
            end = start.replace(year=y + 1, month=1) if m == 12 else start.replace(month=m + 1)
        else:
            return None, None
        return start, end

    def _get_bucket(quota_rows, ws_id, period, now_dt):
        ps, _ = _quota_window(now_dt, period)
        if ps is None:
            return None
        ps_i = _iso(ps)
        for b in quota_rows:
            if isinstance(b, dict) and b.get("workspace_id") == ws_id and b.get("period") == period and b.get("period_start") == ps_i:
                return b
        return None

    def _enforce_quota(tool_req_row, quota_rows, ws_id, estimated_cost):
        now_dt = _now()
        ws_buckets = [b for b in quota_rows if isinstance(b, dict) and b.get("workspace_id") == ws_id]
        if not ws_buckets:
            tool_req_row["status"] = "failed"
            tool_req_row["error"] = {"code": "quota_exceeded", "message": "No quota bucket configured for workspace"}
            tool_req_row["updated_at"] = _iso(now_dt)
            tool_req_row["completed_at"] = _iso(now_dt)
            return False, "UNAUTHORIZED", "No quota bucket configured for workspace"

        enforced_any = False
        for period in ("minute", "hour", "day", "month"):
            b = _get_bucket(quota_rows, ws_id, period, now_dt)
            if not b:
                continue
            enforced_any = True
            mr, ur = b.get("max_requests"), b.get("used_requests")
            mc, uc = b.get("max_upstream_cost_usd_micros"), b.get("used_upstream_cost_usd_micros")
            if not isinstance(mr, int) or not isinstance(ur, int) or not isinstance(mc, int) or not isinstance(uc, int):
                tool_req_row["status"] = "failed"
                tool_req_row["error"] = {"code": "quota_exceeded", "message": "Invalid quota bucket configuration"}
                tool_req_row["updated_at"] = _iso(now_dt)
                tool_req_row["completed_at"] = _iso(now_dt)
                return False, "UNAUTHORIZED", "Invalid quota bucket configuration"
            if ur + 1 > mr or uc + int(estimated_cost) > mc:
                tool_req_row["status"] = "failed"
                tool_req_row["error"] = {"code": "quota_exceeded", "message": "Quota exceeded for current window"}
                tool_req_row["updated_at"] = _iso(now_dt)
                tool_req_row["completed_at"] = _iso(now_dt)
                return False, "QUOTA_EXCEEDED", "Quota exceeded for current window"
        if not enforced_any:
            tool_req_row["status"] = "failed"
            tool_req_row["error"] = {"code": "quota_exceeded", "message": "No active quota window found for workspace"}
            tool_req_row["updated_at"] = _iso(now_dt)
            tool_req_row["completed_at"] = _iso(now_dt)
            return False, "UNAUTHORIZED", "No active quota window found for workspace"
        return True, None, None

    def _account_quota(quota_rows, ws_id, upstream_cost):
        now_dt = _now()
        for period in ("minute", "hour", "day", "month"):
            b = _get_bucket(quota_rows, ws_id, period, now_dt)
            if not b:
                continue
            b["used_requests"] = int(b.get("used_requests", 0)) + 1
            b["used_upstream_cost_usd_micros"] = int(b.get("used_upstream_cost_usd_micros", 0)) + int(upstream_cost)
            b["updated_at"] = _iso(now_dt)

    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    query = query.strip()

    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 50:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 50")
    else:
        limit = 10

    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided")
    if isinstance(idempotency_key, str):
        idempotency_key = idempotency_key.strip()

    t0 = time.time()
    api_key_row, ws_row, auth_reason = _resolve_context()
    if not api_key_row or not ws_row:
        return _err("UNAUTHORIZED", "API key is missing or invalid", reason=auth_reason)

    tool_requests = _load("tool_requests.json")
    if not isinstance(tool_requests, list):
        tool_requests = []

    if idempotency_key:
        for tr in tool_requests:
            if isinstance(tr, dict) and tr.get("workspace_id") == ws_row.get("id") and tr.get("api_key_id") == api_key_row.get("id") and tr.get("tool_name") == "search_web" and tr.get("idempotency_key") == idempotency_key:
                now_dt = _now()
                api_keys = _load("api_keys.json")
                if isinstance(api_keys, list):
                    for k in api_keys:
                        if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                            k["last_used_at"] = _iso(now_dt)
                            k["updated_at"] = _iso(now_dt)
                            break
                    _save("api_keys.json", api_keys)
                return {"tool_request": tr, "latency_ms": int((time.time() - t0) * 1000), "idempotent_replay": True}

    now_dt = _now()
    req_id = _new_ulid("jina_req")
    tr = {
        "id": req_id,
        "workspace_id": ws_row.get("id"),
        "api_key_id": api_key_row.get("id"),
        "tool_name": "search_web",
        "status": "queued",
        "input": {"query": query, "limit": limit, "idempotency_key": idempotency_key} if idempotency_key else {"query": query, "limit": limit},
        "output": None,
        "error": None,
        "idempotency_key": idempotency_key,
        "client_ip": _extra.get("client_ip") if isinstance(_extra.get("client_ip"), str) else None,
        "user_agent": _extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None,
        "upstream_provider": "jina_ai",
        "upstream_endpoint": "/v1/search",
        "upstream_request_id": None,
        "upstream_latency_ms": None,
        "total_latency_ms": None,
        "upstream_cost_usd_micros": 0,
        "created_at": _iso(now_dt),
        "updated_at": _iso(now_dt),
        "started_at": None,
        "completed_at": None,
    }

    if ws_row.get("status") in ("suspended", "closed"):
        tr["status"] = "failed"
        tr["error"] = {"code": "workspace_inactive", "message": f"Workspace status is {ws_row.get('status')}"}
        tr["completed_at"] = _iso(now_dt)
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list):
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                    k["last_used_at"] = _iso(now_dt)
                    k["updated_at"] = _iso(now_dt)
                    break
            _save("api_keys.json", api_keys)
        return {"tool_request": tr}

    quota_rows = _load("quota_buckets.json")
    if not isinstance(quota_rows, list):
        quota_rows = []
    estimated_cost = 1500  # micro-USD
    ok, fail_code, fail_msg = _enforce_quota(tr, quota_rows, ws_row.get("id"), estimated_cost)
    if not ok:
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list):
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                    k["last_used_at"] = _iso(_now())
                    k["updated_at"] = _iso(_now())
                    break
            _save("api_keys.json", api_keys)
        return _err(fail_code, fail_msg, tool_request=tr, reason="quota_exceeded")

    tr["status"] = "running"
    tr["started_at"] = _iso(_now())
    tr["updated_at"] = tr["started_at"]

    # "Upstream" results: use existing search_result artifacts in this workspace if available; else create 0..N new.
    web_artifacts = _load("web_artifacts.json")
    if not isinstance(web_artifacts, list):
        web_artifacts = []

    # Collect some existing search_result artifacts in this workspace
    existing = [a for a in web_artifacts if isinstance(a, dict) and a.get("workspace_id") == ws_row.get("id") and a.get("artifact_type") == "search_result"]
    existing = sorted(existing, key=lambda x: (x.get("created_at") or ""), reverse=True)[:limit]

    results = []
    created_ids = []

    def _mk_result_from_art(a):
        return {
            "title": a.get("title"),
            "url": a.get("source_url"),
            "snippet": a.get("snippet") or (a.get("content_text")[:200] if isinstance(a.get("content_text"), str) else None),
            "artifact_id": a.get("id"),
            "metadata": a.get("metadata") if isinstance(a.get("metadata"), dict) else {},
        }

    # If no existing, create a few deterministic placeholder artifacts (allowed 0..N)
    if not existing:
        n = min(limit, 5)
        now2 = _now()
        for i in range(n):
            art_id = _new_ulid("jina_art")
            a = {
                "id": art_id,
                "workspace_id": ws_row.get("id"),
                "tool_request_id": req_id,
                "artifact_type": "search_result",
                "source_url": f"https://example.com/search?q={query.replace(' ', '+')}&i={i}",
                "title": f"Result {i+1} for {query}",
                "content_text": None,
                "content_html": None,
                "snippet": f"Search snippet {i+1} for query: {query}",
                "metadata": {"rank": i + 1, "query": query},
                "content_sha256": None,
                "expires_at": None,
                "created_at": _iso(now2),
                "updated_at": _iso(now2),
            }
            web_artifacts.append(a)
            created_ids.append(art_id)
            results.append(_mk_result_from_art(a))
        _save("web_artifacts.json", web_artifacts)
    else:
        results = [_mk_result_from_art(a) for a in existing]

    done = _now()
    tr["status"] = "succeeded"
    tr["output"] = {"query": query, "limit": limit, "results": results}
    tr["error"] = None
    tr["upstream_request_id"] = _new_ulid("jina_up")
    tr["upstream_latency_ms"] = max(1, int((time.time() - t0) * 1000) - 1)
    tr["upstream_cost_usd_micros"] = int(estimated_cost)
    tr["completed_at"] = _iso(done)
    tr["total_latency_ms"] = int((time.time() - t0) * 1000)
    tr["updated_at"] = _iso(done)

    tool_requests.append(tr)
    _save("tool_requests.json", tool_requests)

    api_keys = _load("api_keys.json")
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                k["last_used_at"] = _iso(done)
                k["updated_at"] = _iso(done)
                break
        _save("api_keys.json", api_keys)

    _account_quota(quota_rows, ws_row.get("id"), tr["upstream_cost_usd_micros"])
    _save("quota_buckets.json", quota_rows)

    return {"tool_request": tr}

def fact_check(statement, idempotency_key=None, **_extra):
    import json, os, datetime, secrets, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0217000" if __import__("os").path.isdir("./environment_mix/0217000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_ulid(prefix):
        ms = int(time.time() * 1000)
        ts = ms.to_bytes(6, "big", signed=False)
        rand = secrets.token_bytes(10)
        n = int.from_bytes(ts + rand, "big")
        out = []
        for _ in range(26):
            n, r = divmod(n, 32)
            out.append(_CROCKFORD[r])
        return f"{prefix}_" + "".join(reversed(out))

    def _parse_bearer(v):
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.lower().startswith("bearer "):
            s = s[7:].strip()
        return s or None

    def _extract_token(extra):
        for k in ("api_key", "apiKey", "key", "token", "authorization", "Authorization", "x_api_key", "x-api-key"):
            if k in extra:
                tok = _parse_bearer(extra.get(k))
                if tok:
                    return tok
        return None

    def _resolve_context():
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        if not isinstance(api_keys, list): api_keys = []
        if not isinstance(workspaces, list): workspaces = []

        token = _extract_token(_extra)
        if token:
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == token and k.get("status") == "active":
                    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
                    if ws and ws.get("status") in ("active", "suspended", "closed"):
                        return k, ws, "id"
            for k in api_keys:
                if not isinstance(k, dict) or k.get("status") != "active":
                    continue
                kp = k.get("key_prefix")
                if isinstance(kp, str) and kp and token.startswith(kp):
                    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
                    if ws and ws.get("status") in ("active", "suspended", "closed"):
                        return k, ws, "prefix"
            return None, None, "invalid_api_key"

        for k in api_keys:
            if not isinstance(k, dict) or k.get("status") != "active":
                continue
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
            if ws and ws.get("status") in ("active", "suspended", "closed"):
                return k, ws, "ambient"
        return None, None, "missing_api_key"

    def _quota_window(now_dt, period):
        if period == "minute":
            start = now_dt.replace(second=0, microsecond=0); end = start + datetime.timedelta(minutes=1)
        elif period == "hour":
            start = now_dt.replace(minute=0, second=0, microsecond=0); end = start + datetime.timedelta(hours=1)
        elif period == "day":
            start = now_dt.replace(hour=0, minute=0, second=0, microsecond=0); end = start + datetime.timedelta(days=1)
        elif period == "month":
            start = now_dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
            y, m = start.year, start.month
            end = start.replace(year=y + 1, month=1) if m == 12 else start.replace(month=m + 1)
        else:
            return None, None
        return start, end

    def _get_bucket(quota_rows, ws_id, period, now_dt):
        ps, _ = _quota_window(now_dt, period)
        if ps is None:
            return None
        ps_i = _iso(ps)
        for b in quota_rows:
            if isinstance(b, dict) and b.get("workspace_id") == ws_id and b.get("period") == period and b.get("period_start") == ps_i:
                return b
        return None

    def _enforce_quota(tool_req_row, quota_rows, ws_id, estimated_cost):
        now_dt = _now()
        ws_buckets = [b for b in quota_rows if isinstance(b, dict) and b.get("workspace_id") == ws_id]
        if not ws_buckets:
            tool_req_row["status"] = "failed"
            tool_req_row["error"] = {"code": "quota_exceeded", "message": "No quota bucket configured for workspace"}
            tool_req_row["updated_at"] = _iso(now_dt)
            tool_req_row["completed_at"] = _iso(now_dt)
            return False, "UNAUTHORIZED", "No quota bucket configured for workspace"

        enforced_any = False
        for period in ("minute", "hour", "day", "month"):
            b = _get_bucket(quota_rows, ws_id, period, now_dt)
            if not b:
                continue
            enforced_any = True
            mr, ur = b.get("max_requests"), b.get("used_requests")
            mc, uc = b.get("max_upstream_cost_usd_micros"), b.get("used_upstream_cost_usd_micros")
            if not isinstance(mr, int) or not isinstance(ur, int) or not isinstance(mc, int) or not isinstance(uc, int):
                tool_req_row["status"] = "failed"
                tool_req_row["error"] = {"code": "quota_exceeded", "message": "Invalid quota bucket configuration"}
                tool_req_row["updated_at"] = _iso(now_dt)
                tool_req_row["completed_at"] = _iso(now_dt)
                return False, "UNAUTHORIZED", "Invalid quota bucket configuration"
            if ur + 1 > mr or uc + int(estimated_cost) > mc:
                tool_req_row["status"] = "failed"
                tool_req_row["error"] = {"code": "quota_exceeded", "message": "Quota exceeded for current window"}
                tool_req_row["updated_at"] = _iso(now_dt)
                tool_req_row["completed_at"] = _iso(now_dt)
                return False, "QUOTA_EXCEEDED", "Quota exceeded for current window"
        if not enforced_any:
            tool_req_row["status"] = "failed"
            tool_req_row["error"] = {"code": "quota_exceeded", "message": "No active quota window found for workspace"}
            tool_req_row["updated_at"] = _iso(now_dt)
            tool_req_row["completed_at"] = _iso(now_dt)
            return False, "UNAUTHORIZED", "No active quota window found for workspace"
        return True, None, None

    def _account_quota(quota_rows, ws_id, upstream_cost):
        now_dt = _now()
        for period in ("minute", "hour", "day", "month"):
            b = _get_bucket(quota_rows, ws_id, period, now_dt)
            if not b:
                continue
            b["used_requests"] = int(b.get("used_requests", 0)) + 1
            b["used_upstream_cost_usd_micros"] = int(b.get("used_upstream_cost_usd_micros", 0)) + int(upstream_cost)
            b["updated_at"] = _iso(now_dt)

    if not isinstance(statement, str) or not statement.strip():
        return _err("VALIDATION_ERROR", "statement must be a non-empty string")
    statement = statement.strip()

    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided")
    if isinstance(idempotency_key, str):
        idempotency_key = idempotency_key.strip()

    t0 = time.time()
    api_key_row, ws_row, auth_reason = _resolve_context()
    if not api_key_row or not ws_row:
        return _err("UNAUTHORIZED", "API key is missing or invalid", reason=auth_reason)

    tool_requests = _load("tool_requests.json")
    if not isinstance(tool_requests, list):
        tool_requests = []

    if idempotency_key:
        for tr in tool_requests:
            if isinstance(tr, dict) and tr.get("workspace_id") == ws_row.get("id") and tr.get("api_key_id") == api_key_row.get("id") and tr.get("tool_name") == "fact_check" and tr.get("idempotency_key") == idempotency_key:
                now_dt = _now()
                api_keys = _load("api_keys.json")
                if isinstance(api_keys, list):
                    for k in api_keys:
                        if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                            k["last_used_at"] = _iso(now_dt)
                            k["updated_at"] = _iso(now_dt)
                            break
                    _save("api_keys.json", api_keys)
                return {"tool_request": tr, "latency_ms": int((time.time() - t0) * 1000), "idempotent_replay": True}

    now_dt = _now()
    req_id = _new_ulid("jina_req")
    tr = {
        "id": req_id,
        "workspace_id": ws_row.get("id"),
        "api_key_id": api_key_row.get("id"),
        "tool_name": "fact_check",
        "status": "queued",
        "input": {"statement": statement, "idempotency_key": idempotency_key} if idempotency_key else {"statement": statement},
        "output": None,
        "error": None,
        "idempotency_key": idempotency_key,
        "client_ip": _extra.get("client_ip") if isinstance(_extra.get("client_ip"), str) else None,
        "user_agent": _extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None,
        "upstream_provider": "jina_ai",
        "upstream_endpoint": "/v1/fact-check",
        "upstream_request_id": None,
        "upstream_latency_ms": None,
        "total_latency_ms": None,
        "upstream_cost_usd_micros": 0,
        "created_at": _iso(now_dt),
        "updated_at": _iso(now_dt),
        "started_at": None,
        "completed_at": None,
    }

    if ws_row.get("status") in ("suspended", "closed"):
        tr["status"] = "failed"
        tr["error"] = {"code": "workspace_inactive", "message": f"Workspace status is {ws_row.get('status')}"}
        tr["completed_at"] = _iso(now_dt)
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list):
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                    k["last_used_at"] = _iso(now_dt)
                    k["updated_at"] = _iso(now_dt)
                    break
            _save("api_keys.json", api_keys)
        return {"tool_request": tr}

    quota_rows = _load("quota_buckets.json")
    if not isinstance(quota_rows, list):
        quota_rows = []
    estimated_cost = 1200
    ok, fail_code, fail_msg = _enforce_quota(tr, quota_rows, ws_row.get("id"), estimated_cost)
    if not ok:
        tool_requests.append(tr)
        _save("tool_requests.json", tool_requests)
        api_keys = _load("api_keys.json")
        if isinstance(api_keys, list):
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                    k["last_used_at"] = _iso(_now())
                    k["updated_at"] = _iso(_now())
                    break
            _save("api_keys.json", api_keys)
        return _err(fail_code, fail_msg, tool_request=tr, reason="quota_exceeded")

    tr["status"] = "running"
    tr["started_at"] = _iso(_now())
    tr["updated_at"] = tr["started_at"]

    # "Upstream" fact check: create a simple verdict + optional evidence from existing artifacts
    web_artifacts = _load("web_artifacts.json")
    if not isinstance(web_artifacts, list):
        web_artifacts = []
    existing_ev = [a for a in web_artifacts if isinstance(a, dict) and a.get("workspace_id") == ws_row.get("id") and a.get("artifact_type") == "fact_check_evidence"]
    existing_ev = sorted(existing_ev, key=lambda x: (x.get("created_at") or ""), reverse=True)[:3]

    evidences = []
    for a in existing_ev:
        evidences.append({
            "title": a.get("title"),
            "url": a.get("source_url"),
            "snippet": a.get("snippet") or (a.get("content_text")[:240] if isinstance(a.get("content_text"), str) else None),
            "artifact_id": a.get("id"),
            "metadata": a.get("metadata") if isinstance(a.get("metadata"), dict) else {},
        })

    # If none, it's allowed 0..N; we'll create 1 minimal evidence artifact to satisfy persistence ability.
    if not evidences:
        now2 = _now()
        art_id = _new_ulid("jina_art")
        a = {
            "id": art_id,
            "workspace_id": ws_row.get("id"),
            "tool_request_id": req_id,
            "artifact_type": "fact_check_evidence",
            "source_url": None,
            "title": "Evidence summary",
            "content_text": f"Evidence placeholder for statement: {statement}",
            "content_html": None,
            "snippet": "Grounding evidence placeholder.",
            "metadata": {"statement": statement},
            "content_sha256": None,
            "expires_at": None,
            "created_at": _iso(now2),
            "updated_at": _iso(now2),
        }
        web_artifacts.append(a)
        _save("web_artifacts.json", web_artifacts)
        evidences.append({
            "title": a.get("title"),
            "url": a.get("source_url"),
            "snippet": a.get("snippet"),
            "artifact_id": a.get("id"),
            "metadata": a.get("metadata"),
        })

    verdict = "likely_true" if len(statement) % 2 == 0 else "uncertain"

    done = _now()
    tr["status"] = "succeeded"
    tr["output"] = {"statement": statement, "verdict": verdict, "evidence": evidences}
    tr["error"] = None
    tr["upstream_request_id"] = _new_ulid("jina_up")
    tr["upstream_latency_ms"] = max(1, int((time.time() - t0) * 1000) - 1)
    tr["upstream_cost_usd_micros"] = int(estimated_cost)
    tr["completed_at"] = _iso(done)
    tr["total_latency_ms"] = int((time.time() - t0) * 1000)
    tr["updated_at"] = _iso(done)

    tool_requests.append(tr)
    _save("tool_requests.json", tool_requests)

    api_keys = _load("api_keys.json")
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                k["last_used_at"] = _iso(done)
                k["updated_at"] = _iso(done)
                break
        _save("api_keys.json", api_keys)

    _account_quota(quota_rows, ws_row.get("id"), tr["upstream_cost_usd_micros"])
    _save("quota_buckets.json", quota_rows)

