def list_tool_requests(status=None, tool_name=None, idempotency_key=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0217000" if __import__("os").path.isdir("./environment_mix/0217000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_bearer(v):
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.lower().startswith("bearer "):
            s = s[7:].strip()
        return s or None

    def _extract_token(extra):
        for k in ("api_key", "apiKey", "key", "token", "authorization", "Authorization", "x_api_key", "x-api-key"):
            if k in extra:
                tok = _parse_bearer(extra.get(k))
                if tok:
                    return tok
        return None

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _resolve_context():
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        if not isinstance(api_keys, list): api_keys = []
        if not isinstance(workspaces, list): workspaces = []

        token = _extract_token(_extra)
        if token:
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == token and k.get("status") == "active":
                    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
                    if ws and ws.get("status") in ("active", "suspended", "closed"):
                        return k, ws, "id"
            for k in api_keys:
                if not isinstance(k, dict) or k.get("status") != "active":
                    continue
                kp = k.get("key_prefix")
                if isinstance(kp, str) and kp and token.startswith(kp):
                    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
                    if ws and ws.get("status") in ("active", "suspended", "closed"):
                        return k, ws, "prefix"
            return None, None, "invalid_api_key"

        for k in api_keys:
            if not isinstance(k, dict) or k.get("status") != "active":
                continue
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
            if ws and ws.get("status") in ("active", "suspended", "closed"):
                return k, ws, "ambient"
        return None, None, "missing_api_key"

    valid_status = {None, "queued", "running", "succeeded", "failed", "cancelled"}
    if status not in valid_status:
        return _err("VALIDATION_ERROR", "Invalid status value")
    valid_tool = {None, "read_webpage", "search_web", "fact_check"}
    if tool_name not in valid_tool:
        return _err("VALIDATION_ERROR", "Invalid tool_name value")
    if idempotency_key is not None and (not isinstance(idempotency_key, str) or not idempotency_key.strip()):
        return _err("VALIDATION_ERROR", "idempotency_key must be a non-empty string when provided")
    if isinstance(idempotency_key, str):
        idempotency_key = idempotency_key.strip()

    ca = _parse_dt(created_after)
    if created_after is not None and ca is None:
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 date-time string")
    cb = _parse_dt(created_before)
    if created_before is not None and cb is None:
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 date-time string")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    api_key_row, ws_row, auth_reason = _resolve_context()
    if not api_key_row or not ws_row:
        return _err("UNAUTHORIZED", "API key is missing or invalid", reason=auth_reason)

    tool_requests = _load("tool_requests.json")
    if not isinstance(tool_requests, list):
        tool_requests = []

    rows = [r for r in tool_requests if isinstance(r, dict) and r.get("workspace_id") == ws_row.get("id")]

    if status:
        rows = [r for r in rows if r.get("status") == status]
    if tool_name:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if idempotency_key:
        rows = [r for r in rows if r.get("idempotency_key") == idempotency_key]
    if ca:
        rows = [r for r in rows if isinstance(r.get("created_at"), str) and (_parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) >= ca]
    if cb:
        rows = [r for r in rows if isinstance(r.get("created_at"), str) and (_parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) <= cb]

    rows.sort(key=lambda r: r.get("created_at") or "", reverse=True)

    # Cursor is an opaque created_at marker + id: "created_at|id"
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or "|" not in cursor:
            return _err("VALIDATION_ERROR", "cursor is invalid")
        c_created, c_id = cursor.split("|", 1)
        # find index after this item
        for i, r in enumerate(rows):
            if r.get("id") == c_id and (r.get("created_at") or "") == c_created:
                start = i + 1
                break

    page = rows[start:start + limit]
    has_more = start + limit < len(rows)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = f"{last.get('created_at') or ''}|{last.get('id') or ''}"

    # Update last_used_at
    now_dt = _now()
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, list):
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                k["last_used_at"] = _iso(now_dt)
                k["updated_at"] = _iso(now_dt)
                break
        _save("api_keys.json", api_keys)

    return {"data": page, "meta": {"total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

def get_tool_request(id, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0217000" if __import__("os").path.isdir("./environment_mix/0217000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str) or not s.strip():
            return None
        st = s.strip()
        try:
            if st.endswith("Z"):
                return datetime.datetime.fromisoformat(st[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(st)
        except Exception:
            return None

    def _parse_bearer(v):
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.lower().startswith("bearer "):
            s = s[7:].strip()
        return s or None

    def _extract_token(extra):
        for k in ("api_key", "apiKey", "key", "token", "authorization", "Authorization", "x_api_key", "x-api-key"):
            if k in extra:
                tok = _parse_bearer(extra.get(k))
                if tok:
                    return tok
        return None

    def _ulidish(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_" + "".join(random.choice(alphabet) for _ in range(26))

    def _log_request(tool_name, workspace_id, api_key_id, status, latency_ms, input_obj, output_obj=None, err_obj=None, upstream_endpoint=None, upstream_latency_ms=None, upstream_cost=0):
        tool_reqs = _load("tool_requests.json")
        if not isinstance(tool_reqs, list):
            tool_reqs = []
        now = _now()
        rid = _ulidish("jina_req")
        row = {
            "id": rid,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "status": status,
            "input": input_obj if isinstance(input_obj, dict) else {"raw": input_obj},
            "output": output_obj,
            "error": err_obj,
            "idempotency_key": None,
            "client_ip": _extra.get("client_ip") if isinstance(_extra.get("client_ip"), str) else None,
            "user_agent": _extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None,
            "upstream_provider": "jina_ai",
            "upstream_endpoint": upstream_endpoint,
            "upstream_request_id": None,
            "upstream_latency_ms": upstream_latency_ms,
            "total_latency_ms": latency_ms,
            "upstream_cost_usd_micros": int(upstream_cost) if isinstance(upstream_cost, int) and upstream_cost >= 0 else 0,
            "created_at": _iso(now),
            "updated_at": _iso(now),
            "started_at": None,
            "completed_at": _iso(now) if status in ("succeeded", "failed", "cancelled") else None,
        }
        tool_reqs.append(row)
        _save("tool_requests.json", tool_reqs)
        return row

    def _auth_and_resolve_workspace(token, api_keys, workspaces, tool_reqs, requested_req_id):
        # If token provided: authenticate by (id match) OR (key_prefix match). Never compare against key_hash.
        # If token missing: resolve "ambient auth" by finding any workspace that contains the referenced tool_request.
        if token:
            tok = token.strip()
            key = None
            for r in api_keys:
                if not isinstance(r, dict):
                    continue
                if r.get("status") != "active":
                    continue
                if r.get("id") == tok or r.get("key_prefix") == tok:
                    key = r
                    break
            if not key:
                return None, None, _err("UNAUTHORIZED", "API key missing/invalid")
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == key.get("workspace_id")), None)
            if not ws:
                return None, None, _err("UNAUTHORIZED", "API key is not associated with a valid workspace")
            return ws, key, None

        # Ambient: choose a workspace that can serve the call by locating the tool request id across store.
        req = next((r for r in tool_reqs if isinstance(r, dict) and r.get("id") == requested_req_id), None)
        if not req:
            # can't resolve ambient context; treat as UNAUTHORIZED per contract for missing/invalid key
            return None, None, _err("UNAUTHORIZED", "API key missing/invalid")
        ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == req.get("workspace_id")), None)
        if not ws:
            return None, None, _err("UNAUTHORIZED", "Workspace context unavailable")
        return ws, None, None

    # Validate input
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    req_id = id.strip()

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    tool_reqs = _load("tool_requests.json")
    if not isinstance(tool_reqs, list):
        tool_reqs = []

    token = _extract_token(_extra)
    ws, key, auth_err = _auth_and_resolve_workspace(token, api_keys, workspaces, tool_reqs, req_id)

    # Always log this invocation (reads included), even if it fails auth.
    if auth_err:
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(
            tool_name="read_webpage",
            workspace_id=(workspaces[0]["id"] if workspaces and isinstance(workspaces[0], dict) and "id" in workspaces[0] else "unknown"),
            api_key_id=None,
            status="failed",
            latency_ms=latency_ms,
            input_obj={"operation": "get_tool_request", "id": req_id},
            output_obj=None,
            err_obj={"code": "unauthorized", "message": auth_err["error"]["message"], "upstream_status": None, "retriable": False},
            upstream_endpoint=None,
            upstream_latency_ms=None,
            upstream_cost=0,
        )
        return auth_err

    # Find request in workspace
    found = None
    for r in tool_reqs:
        if isinstance(r, dict) and r.get("id") == req_id and r.get("workspace_id") == ws.get("id"):
            found = r
            break
    if not found:
        latency_ms = int((time.time() - t0) * 1000)
        _log_request(
            tool_name="read_webpage",
            workspace_id=ws.get("id"),
            api_key_id=(key.get("id") if key else None),
            status="failed",
            latency_ms=latency_ms,
            input_obj={"operation": "get_tool_request", "id": req_id},
            output_obj=None,
            err_obj={"code": "not_found", "message": "Tool request not found in this workspace", "upstream_status": None, "retriable": False},
            upstream_endpoint=None,
            upstream_latency_ms=None,
            upstream_cost=0,
        )
        return _err("NOT_FOUND", "Tool request not found in your workspace")

    # If authenticated via key, update last_used_at
    if key is not None:
        now_iso = _iso(_now())
        changed = False
        for i, r in enumerate(api_keys):
            if isinstance(r, dict) and r.get("id") == key.get("id"):
                api_keys[i] = dict(r)
                api_keys[i]["last_used_at"] = now_iso
                api_keys[i]["updated_at"] = now_iso
                changed = True
                break
        if changed:
            _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    _log_request(
        tool_name="read_webpage",
        workspace_id=ws.get("id"),
        api_key_id=(key.get("id") if key else None),
        status="succeeded",
        latency_ms=latency_ms,
        input_obj={"operation": "get_tool_request", "id": req_id},
        output_obj={"tool_request_id": req_id},
        err_obj=None,
        upstream_endpoint=None,
        upstream_latency_ms=None,
        upstream_cost=0,
    )

    return {"data": found}

