    updated["updated_at"] = _iso(now)
    updated["completed_at"] = _iso(now)
    # cancellation is a completion; per rule, output must be null unless succeeded
    updated["output"] = None
    # record reason in error payload (cancelled has no error field constraint, but keep error null for cancelled)
    updated["error"] = None
    # annotate reason into input metadata for audit without violating schema
    inp = updated.get("input")
    if not isinstance(inp, dict):
        inp = {"raw": inp}
    if reason:
        meta = inp.get("_meta")
        if not isinstance(meta, dict):
            meta = {}
        meta["cancel_reason"] = reason
        inp["_meta"] = meta
    inp["_meta"] = inp.get("_meta") if isinstance(inp.get("_meta"), dict) else inp.get("_meta")
    updated["input"] = inp

    tool_reqs[idx] = updated
    _save("tool_requests.json", tool_reqs)

    # If authenticated via key, update last_used_at
    if key is not None:
        now_iso = _iso(now)
        changed = False
        for i, r in enumerate(api_keys):
            if isinstance(r, dict) and r.get("id") == key.get("id"):
                api_keys[i] = dict(r)
                api_keys[i]["last_used_at"] = now_iso
                api_keys[i]["updated_at"] = now_iso
                changed = True
                break
        if changed:
            _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    _log_request(
        tool_name="read_webpage",
        workspace_id=ws.get("id"),
        api_key_id=(key.get("id") if key else None),
        status="succeeded",
        latency_ms=latency_ms,
        input_obj={"operation": "cancel_tool_request", "id": req_id, "reason": reason},
        output_obj={"cancelled_request_id": req_id},
        err_obj=None,
        upstream_endpoint=None,
        upstream_latency_ms=None,
        upstream_cost=0,
    )

    return {"data": updated}

def list_web_artifacts(tool_request_id=None, artifact_type=None, source_url=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0217000" if __import__("os").path.isdir("./environment_mix/0217000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _hash_key_sha256(secret):
        return hashlib.sha256(secret.encode("utf-8")).hexdigest()

    def _parse_auth():
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")

        token = None
        for k in ("api_key", "apiKey", "key", "token", "authorization", "Authorization", "x_api_key", "x-api-key"):
            if k in _extra and isinstance(_extra.get(k), str) and _extra.get(k).strip():
                token = _extra.get(k).strip()
                break

        def _workspace_ok(ws):
            return ws and ws.get("status") in ("active", "suspended", "closed")

        if token is not None:
            for r in api_keys:
                if r.get("id") == token and r.get("status") == "active":
                    ws = next((w for w in workspaces if w.get("id") == r.get("workspace_id")), None)
                    if _workspace_ok(ws):
                        return r, ws
            token_hash = _hash_key_sha256(token)
            candidates = [r for r in api_keys if r.get("status") == "active" and isinstance(r.get("key_prefix"), str)]
            for r in candidates:
                kp = r.get("key_prefix")
                if isinstance(kp, str) and 6 <= len(kp) <= 24 and token.startswith(kp):
                    if r.get("key_hash") == token_hash:
                        ws = next((w for w in workspaces if w.get("id") == r.get("workspace_id")), None)
                        if _workspace_ok(ws):
                            return r, ws
            for r in candidates:
                if r.get("key_hash") == token_hash:
                    ws = next((w for w in workspaces if w.get("id") == r.get("workspace_id")), None)
                    if _workspace_ok(ws):
                        return r, ws
            return None, None

        for r in api_keys:
            if r.get("status") != "active":
                continue
            ws = next((w for w in workspaces if w.get("id") == r.get("workspace_id")), None)
            if _workspace_ok(ws):
                return r, ws
        return None, None

    def _decode_cursor(cur):
        if not cur:
            return 0
        if not isinstance(cur, str):
            return None
        # Simple opaque cursor: "o:<offset>:<sha>"
        parts = cur.split(":")
        if len(parts) != 3 or parts[0] != "o":
            return None
        try:
            offset = int(parts[1])
        except Exception:
            return None
        if offset < 0:
            return None
        return offset

    def _encode_cursor(offset, salt):
        digest = hashlib.sha256((salt + ":" + str(offset)).encode("utf-8")).hexdigest()[:12]
        return f"o:{offset}:{digest}"

    if tool_request_id is not None and (not isinstance(tool_request_id, str) or not tool_request_id.strip()):
        return _err("VALIDATION_ERROR", "tool_request_id must be a non-empty string")
    if artifact_type is not None:
        if not isinstance(artifact_type, str):
            return _err("VALIDATION_ERROR", "artifact_type must be a string")
        if artifact_type not in ("webpage", "search_result", "fact_check_evidence"):
            return _err("VALIDATION_ERROR", "artifact_type must be one of: webpage, search_result, fact_check_evidence")
    if source_url is not None and (not isinstance(source_url, str) or not source_url.strip()):
        return _err("VALIDATION_ERROR", "source_url must be a non-empty string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    offset = _decode_cursor(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "cursor is invalid")

    api_key_row, ws_row = _parse_auth()
    if not api_key_row or not ws_row:
        return _err("UNAUTHORIZED", "API key is missing or invalid")

    # Update last_used_at on successful authentication
    api_keys = _load("api_keys.json")
    for r in api_keys:
        if r.get("id") == api_key_row.get("id"):
            r["last_used_at"] = _now_iso()
            r["updated_at"] = _now_iso()
            _save("api_keys.json", api_keys)
            break

    artifacts = _load("web_artifacts.json")
    # Filter to workspace
    rows = [a for a in artifacts if a.get("workspace_id") == ws_row.get("id")]

    if tool_request_id is not None:
        rows = [a for a in rows if a.get("tool_request_id") == tool_request_id]
    if artifact_type is not None:
        rows = [a for a in rows if a.get("artifact_type") == artifact_type]
    if source_url is not None:
        rows = [a for a in rows if a.get("source_url") == source_url]

    # Enforce FK integrity (artifact tool_request_id must be in same workspace); drop corrupt rows rather than erroring list
    tool_requests = _load("tool_requests.json")
    tr_workspace = {tr.get("id"): tr.get("workspace_id") for tr in tool_requests if isinstance(tr.get("id"), str)}
    rows = [a for a in rows if tr_workspace.get(a.get("tool_request_id")) in (None, ws_row.get("id"))]

    # Sort newest first
    def _sort_key(a):
        return (a.get("created_at") or "", a.get("id") or "")
    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    salt = ws_row.get("id") or "ws"
    next_cursor = _encode_cursor(next_offset, salt) if has_more else None

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

def create_api_key(name, **_extra):
    import json, os, datetime, secrets, hashlib, hmac

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0217000" if __import__("os").path.isdir("./environment_mix/0217000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Minimal ULID-ish generator (lexicographically sortable by time) using stdlib only.
    def _ulid():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

        def enc32(data_bytes):
            # Crockford base32 without padding, for 16 bytes -> 26 chars
            n = int.from_bytes(data_bytes, "big")
            out = []
            for _ in range(26):
                out.append(alphabet[n & 31])
                n >>= 5
            return "".join(reversed(out))

        ts_ms = int(datetime.datetime.now(datetime.timezone.utc).timestamp() * 1000)
        ts_bytes = ts_ms.to_bytes(6, "big", signed=False)
        rand_bytes = secrets.token_bytes(10)
        return enc32(ts_bytes + rand_bytes)

    def _hash_key(plaintext):
        # Store hash (not reversible). Use SHA-256 hex for simplicity.
        return hashlib.sha256(plaintext.encode("utf-8")).hexdigest()

    def _safe_str(v):
        return isinstance(v, str)

    # Validate input
    if not _safe_str(name):
        return _err("VALIDATION_ERROR", "name must be a string")
    name = name.strip()
    if not (1 <= len(name) <= 120):
        return _err("VALIDATION_ERROR", "name length must be between 1 and 120")

    # Ambient authentication: choose a workspace eligible to manage keys.
    # "Refuses with FORBIDDEN if not entitled to manage keys" -> map to UNAUTHORIZED (allowed codes) vs VALIDATION.
    # We'll interpret entitlement by plan: pro/enterprise can manage keys; free cannot.
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")

    eligible_ws = None
    for ws in workspaces:
        if ws.get("status") == "active" and ws.get("plan") in ("pro", "enterprise"):
            eligible_ws = ws
            break

    if eligible_ws is None:
        # Could be because no authenticated/eligible workspace context exists in local store.
        # Return UNAUTHORIZED per contract's allowed codes.
        return _err("UNAUTHORIZED", "Not authorized to manage API keys for any workspace in this environment")

    workspace_id = eligible_ws.get("id")

    # Enforce unique(workspace_id, name)
    for k in api_keys:
        if k.get("workspace_id") == workspace_id and isinstance(k.get("name"), str) and k.get("name") == name:
            return _err("CONFLICT", "An API key with this name already exists in the workspace")

    # Generate plaintext key and prefix; ensure unique key_prefix length 6..24 and unique across all keys
    # We'll use prefix length 8 (common).
    prefix_len = 8
    if prefix_len < 6 or prefix_len > 24:
        return _err("VALIDATION_ERROR", "Internal configuration error: key_prefix length out of bounds")

    existing_prefixes = {k.get("key_prefix") for k in api_keys if isinstance(k.get("key_prefix"), str)}
    plaintext = None
    key_prefix = None
    for _ in range(50):
        candidate = "jina_" + secrets.token_urlsafe(32)
        cand_prefix = candidate[:prefix_len]
        if cand_prefix not in existing_prefixes:
            plaintext = candidate
            key_prefix = cand_prefix
            break
    if plaintext is None:
        return _err("CONFLICT", "Unable to allocate a unique API key prefix; try again")

    # Create key row
    now = _now_iso()
    key_id = _ulid()
    key_row = {
        "id": key_id,
        "workspace_id": workspace_id,
        "name": name,
        "key_prefix": key_prefix,
        "key_hash": _hash_key(plaintext),
        "status": "active",
        "last_used_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Persist
    api_keys.append(key_row)
    _save("api_keys.json", api_keys)

    # Return plaintext exactly once, plus metadata
    # (No further storage of plaintext; caller must store it.)
    return {
        "api_key": {
            "id": key_row["id"],
            "workspace_id": key_row["workspace_id"],
            "name": key_row["name"],
            "key_prefix": key_row["key_prefix"],
            "status": key_row["status"],
            "last_used_at": key_row["last_used_at"],
            "created_at": key_row["created_at"],
            "updated_at": key_row["updated_at"],
        },
        "plaintext_key": plaintext,
    }
